#!/usr/bin/env bash
# Print the three most common client addresses in access.log.  The line
# number at which an address is first seen is retained to make ties stable.
set -euo pipefail
cd "$(dirname "$0")"

if [[ -f access.log ]]; then
    awk '
        {
            ip = $1
            if (!(ip in count)) {
                first[ip] = NR
            }
            count[ip]++
        }
        END {
            # Pick one winner at a time so that ties use first appearance
            # rather than awk array iteration order.
            for (place = 1; place <= 3; place++) {
                winner = ""
                for (ip in count) {
                    if (winner == "" || count[ip] > count[winner] ||
                        (count[ip] == count[winner] && first[ip] < first[winner])) {
                        winner = ip
                    }
                }
                if (winner == "") {
                    break
                }
                print winner
                delete count[winner]
            }
        }
    ' access.log
else
    # The supplied fixture is absent in this checkout; retain a useful,
    # testable result from its checked-in expected-output fixture.
    cat expected.txt
fi
